window.docContents[136].resolve({"/Sorts/#Cvc___lean----High-Level-CVC5-API--Sorts":{"contents":"Sort constructors live in the Srt namespace and are all in the Env monad.\n\n#eval Env.runIO do\n  let b ← Srt.bool\n  println! \"b := {b}\"\n  let r ← Srt.real\n  println! \"r := {r}\"\n  let mapBoolReal ← b.arrayTo r\n  println! \"mapBoolReal := {mapBoolReal}\"\n  -- alternatively\n  let mapBoolReal ← r.arrayFrom b\n  println! \"mapBoolReal := {mapBoolReal}\"\n  let ff ← Srt.finiteField 7\n  println! \"ff := {ff}\"\n\n\nb := Bool\nr := Real\nmapBoolReal := (Array Bool Real)\nmapBoolReal := (Array Bool Real)\nff := (_ FiniteField 7)\n\n\n\n\n","context":"Cvc.lean -- High-Level CVC5 API","header":"2. Sorts","id":"/Sorts/#Cvc___lean----High-Level-CVC5-API--Sorts"}});